window.AULAS = window.AULAS || {};
window.AULAS["aula-09"] = {"id": "aula-09", "titulo": "Aula 9 - Semiologia do sistema genitourinário masculino", "subtitulo": "Pênis, escroto, região inguinal, próstata e urgências do escroto", "pdf": "pdf/aula-09.pdf", "fontes": ["Aula 9 (slides do Prof. Dr. João Vítor Galo Esteves, Censupeg)", "Bates, Bickley: Propedêutica médica", "Porto: Semiologia médica", "Rocco: Semiologia médica"], "resumo": [{"titulo": "1. Método, casos de abertura e anatomia aplicada (slides 2 a 4 e 15)", "pontos": [{"t": "Regra de ouro e sequência (slides 2 e 4)", "sub": ["Exame de rotina com técnica precisa e padronizada; descreva os achados anatômicos antes de nomear a doença.", "Sequência: anamnese dirigida (urina, genitália, sexualidade), pênis, escroto, região inguinal (hérnias, em pé), próstata (toque retal) e registro descritivo.", "Checklist mental de rotina: pênis, escroto e conteúdo, região inguinal (em pé), toque retal e registro médico descritivo."]}, {"t": "Dois pacientes, a mesma sala (slide 3)", "sub": ["J., 16 anos: dor escrotal esquerda súbita, com episódio prévio semelhante que cedeu espontaneamente; janela de minutos a horas (emergência).", "A., 68 anos: noctúria persistente, jato urinário fraco e área endurecida na próstata em exame de rotina; janela de meses a anos (rastreio)."]}, {"t": "Anatomia aplicada ao exame (slide 15)", "sub": ["Pênis e uretra: dois corpos cavernosos e um corpo esponjoso, que contém a uretra e termina na glande; meato uretral em fenda vertical.", "Testículo adulto normal: 4 a 5 cm, ovoide, liso e elástico; o esquerdo costuma ser mais baixo. Epidídimo nodular normal na face posterolateral (não é tumor). Ducto deferente firme, como corda. Túnica vaginal: espaço virtual anterior, propenso à hidrocele.", "Varicocele: a veia testicular esquerda drena perpendicularmente na veia renal esquerda, o que favorece varicocele à esquerda.", "Linfa: pênis e pele escrotal drenam para linfonodos inguinais (palpáveis); testículos drenam para linfonodos retroperitoneais profundos (não palpáveis). O câncer testicular primário não causa linfonodopatia inguinal.", "Região inguinal: espinha ilíaca anterossuperior, tubérculo púbico e ligamento inguinal (inguinal acima, femoral abaixo); anéis inguinais superficial e profundo; canal femoral medial à veia femoral.", "Próstata: cerca de 2,5 cm, dois lobos e sulco mediano raso; apenas a face posterior é acessível ao toque. O lobo mediano é inacessível."]}]}, {"titulo": "2. Anamnese dirigida (slides 16 a 24)", "pontos": [{"t": "Como perguntar sobre genitália e sexualidade (slide 17)", "sub": ["Objetividade e respeito: abordagem neutra, técnica e universal, sem expressões de julgamento.", "Explicar o porquê antes de perguntar.", "Idade e risco ocupacional orientam a suspeita antes mesmo de tocar o paciente.", "O desconforto diminui com método estruturado e postura profissional."]}, {"t": "Sintomas urinários baixos (LUTS) (slide 18)", "sub": ["Obstrutivos (falha de esvaziamento): hesitação inicial, esforço abdominal, jato fraco, fino ou intermitente, gotejamento terminal prolongado e sensação de esvaziamento incompleto.", "Irritativos (falha de armazenamento): polaciúria, urgência miccional, noctúria, incontinência de urgência e disúria."]}, {"t": "Disúria e hematúria (slides 19 e 24)", "sub": ["Disúria isolada, sem polaciúria ou urgência, sugere uretrite.", "Hematúria inicial indica origem uretral ou prostática; terminal sugere colo vesical ou trígono; total indica lesão em rim, ureter ou bexiga.", "Origem do sintoma urinário: total (rim, ureter ou bexiga acima do colo), terminal (colo vesical e trígono), inicial (uretra).", "Pseudo-hematúria: beterraba e rifampicina tingem a urina."]}, {"t": "Secreção uretral, escroto e investigação (slides 20, 21 e 24)", "sub": ["Caracterizar volume, cor, início e relação com exposição sexual; pesquisar úlceras, verrugas, prurido intenso e escoriações (pediculose, escabiose); febre, artrite e conjuntivite sugerem artrite reativa.", "O aspecto da secreção apenas sugere a etiologia; o diagnóstico exige Gram e cultura.", "Dor escrotal súbita é emergência por torção; massa escrotal indolor exige investigação para tumor (ultrassonografia)."]}, {"t": "Função sexual e reprodutiva (slide 22)", "sub": ["Ereção depende de vasos, nervos e testosterona; via superior psicogênica (simpáticos T11 a L2) e via inferior reflexa tátil (parassimpático S2 a S4, nervo pudendo), com liberação de óxido nítrico e vasodilatação.", "Disfunção erétil: primária ou secundária; orgânica ou psicogênica. Ejaculação: precoce, ausente, retrógrada, hemospermia. Libido reduzida sugere depressão, endocrinopatia ou efeito de fármacos.", "Infertilidade: criptorquidia, varicocele e orquite prévia (caxumba).", "Priapismo: ereção persistente, dolorosa e sem desejo, com risco de lesão isquêmica irreversível."]}, {"t": "História sexual e risco de IST: os 5 Ps (slide 23)", "sub": ["Parcerias (número e gênero nos últimos 3 meses), práticas (oral, vaginal, anal), preservativo (frequência e consistência), passado (ISTs e tratamentos prévios) e prevenção (HIV e rastreamento).", "Abordagem empática, modelo de Bates: explicar que as perguntas são feitas a todos, sem julgamento e confidenciais."]}, {"t": "Sinais de alarme (slide 24)", "sub": ["Prostatite aguda: febre com disúria e dor perineal.", "Torção testicular: dor escrotal súbita com elevação testicular.", "Retenção urinária: bexiga distendida, tensa e dolorosa.", "Priapismo persistente: ereção dolorosa prolongada sem desejo sexual."]}]}, {"titulo": "3. Preparo e exame do pênis (slides 26 a 33)", "pontos": [{"t": "Preparo e ética (slide 26)", "sub": ["Explicar cada etapa e solicitar permissão contínua; oferecer acompanhante (chaperone) quando indicado; luvas em todas as etapas.", "Exposição mínima, só da área examinada; paciente em pé ou em decúbito dorsal; explorar recusas com empatia.", "Avise antes que uma ereção reflexa durante o exame tátil é fisiológica e normal."]}, {"t": "Inspeção do pênis (slides 6 e 27)", "sub": ["Pele e prepúcio: integridade, lesões e distribuição pilosa. Manobra obrigatória: retrair o prepúcio, inspecionar e sempre devolvê-lo à posição original.", "Estruturas: glande, sulco balanoprepucial e meato uretral. Esmegma caseoso é fisiológico.", "Fimose: incapacidade mecânica de retrair o prepúcio. Hipospádia: deslocamento congênito ventral do meato.", "Parafimose: prepúcio retraído que não é devolvido causa garroteamento, edema e isquemia da glande: emergência urológica."]}, {"t": "Úlceras genitais: diagnóstico diferencial rápido (slide 29)", "sub": ["Sífilis primária (cancro duro): indolor, úlcera única de base limpa e bordas endurecidas; linfonodos inguinais indolores e firmes.", "Herpes genital: dolorosa, vesículas agrupadas sobre base eritematosa que evoluem para úlceras rasas; linfonodos dolorosos e aumentados.", "Cancroide (cancro mole): dolorosa, úlcera profunda de bordas irregulares e base suja; linfonodos dolorosos e supurativos (bubões).", "Condiloma acuminado (HPV): indolor, verrucoso, em couve-flor; linfonodos normais.", "Toda úlcera persistente exige investigação de etiologia infecciosa ou neoplásica."]}, {"t": "Meato, ordenha uretral e palpação do corpo (slides 32 e 33)", "sub": ["Abertura do meato: compressão anteroposterior da glande entre polegar e indicador.", "Ordenha uretral: expressão firme da base à glande, fundamental se houver queixa de secreção não visível em repouso.", "Palpação do corpo: deslizar entre polegar e indicadores, buscando indurações, nódulos ou hipersensibilidade.", "Placa fibrótica endurecida no dorso sugere doença de Peyronie; induração na face ventral levanta suspeita de estenose uretral ou carcinoma."]}]}, {"titulo": "4. Escroto e testículo (slides 34 a 41)", "pontos": [{"t": "Inspeção do escroto e das virilhas (slide 34)", "sub": ["Levantar o escroto: a face posterior frequentemente oculta lesões fúngicas ou cistos.", "Avaliar simetria, nódulos cutâneos benignos (cistos epidermoides) e distribuição pilosa; hemiescroto hipoplásico levanta suspeita de criptorquidia.", "Inspecionar as virilhas (assimetrias e abaulamentos de hérnias) antes de palpar.", "Assimetria grave ou edema escrotal com cacifo são sentinelas de causas sistêmicas, como insuficiência cardíaca, síndrome nefrótica e cirrose."]}, {"t": "Palpação do testículo (slide 36)", "sub": ["Técnicas: unimanual (polegar à frente, indicador e médio atrás) e bimanual (o testículo desliza entre as mãos, sem apertar).", "Seis parâmetros de descrição: presença, tamanho, forma, consistência, superfície e dor.", "Normal: ovoide, liso, elástico e simétrico; a compressão provoca dor visceral profunda (esperada).", "Alerta: nódulo indolor é suspeita de câncer até prova em contrário (pico de 15 a 34 anos)."]}, {"t": "Epidídimo e funículo (slide 38)", "sub": ["Epidídimo, na face posterossuperior, é avaliado pela manobra de Chevassu; normal: nodular, macio e indolor (não é nódulo).", "Ducto deferente normal: palpável como corda de chicote; alterado: contas de rosário (tuberculose). Funículo espessado com dor: funiculite.", "Regra de ouro: palpar sempre os dois lados, de forma simultânea e comparativa."]}, {"t": "Posição e tamanho do testículo (slide 40)", "sub": ["Bolsa vazia: criptorquidia (retido no trajeto de descida: lombar, ilíaco, inguinal), ectopia (fora do trajeto: perineal, crural, púbica) ou testículo retrátil (o examinador consegue levá-lo à bolsa).", "Testículo pequeno e firme (menor que 2 cm) sugere síndrome de Klinefelter.", "A criptorquidia aumenta significativamente o risco de câncer testicular."]}]}, {"titulo": "5. Massas escrotais, varicocele e hérnias (slides 42 a 52)", "pontos": [{"t": "Massa escrotal: as cinco perguntas (slide 43)", "sub": ["1) Agudo ou crônico? 2) Doloroso ou indolor? 3) Confinado ao escroto (palpo acima da massa)? 4) Transilumina? 5) Reduz?", "Não palpo acima: hérnia. Palpo acima e transilumina: hidrocele ou cisto. Palpo acima, não transilumina e reduz: varicocele. Se não reduz: investigar.", "Alerta: massa dura, indolor e que não transilumina é tumor até prova em contrário."]}, {"t": "Transiluminação (slide 71)", "sub": ["Técnica: sala escura, lanterna de foco direto atrás do escroto.", "Brilho vermelho (transilumina): massa cística, como hidrocele e cisto de epidídimo.", "Sombra opaca (não transilumina): massa sólida, como tumor, orquiepididimite, torção, hematocele e a maioria das hérnias.", "Armadilha: hidrocele irredutível no anel inguinal transilumina, mas pode ser clinicamente indistinguível de hérnia estrangulada."]}, {"t": "Varicocele (slides 46 e 47)", "sub": ["Técnica: examinar em pé e palpar o funículo cerca de 2 cm acima do testículo; a manobra de Valsalva aumenta o diâmetro venoso.", "Achado: saco de vermes acima e atrás do testículo, predomínio à esquerda; colapsa em decúbito.", "Classificação: tipo I, maior que 2 cm (visível); tipo II, 1 a 2 cm (palpável); tipo III, menor que 1 cm (só com Valsalva).", "Alerta: varicocele que não colapsa deitado ou que surge subitamente após os 40 anos exige investigação por compressão retroperitoneal."]}, {"t": "Pesquisa de hérnia inguinal (slide 48)", "sub": ["Passo a passo: paciente em pé, examinador sentado à frente; inspeção em repouso e durante a tosse; indicador invagina a pele escrotal até o anel superficial; pedir tosse ou esforço e sentir o impulso contra o dedo parado; repetir do outro lado.", "Pesquisa femoral: palpar medialmente à artéria femoral, abaixo do ligamento inguinal."]}, {"t": "Hérnias da virilha: diagnóstico diferencial (slide 50)", "sub": ["Indireta: mais frequente; origem no anel profundo; desce ao escroto; toca a ponta do dedo na tosse.", "Direta: menos comum; origem na parede posterior; raramente no escroto; toca a polpa do dedo na tosse.", "Femoral: rara no homem; origem abaixo do ligamento; nunca no escroto.", "Alerta: massa irredutível e dolorosa, com náuseas ou vômitos, é estrangulamento (emergência cirúrgica)."]}]}, {"titulo": "6. Toque retal e próstata (slides 53 a 63)", "pontos": [{"t": "Preparo e posicionamento (slide 56)", "sub": ["Indicações: sintomas de HPB, rastreio e avaliação retal e neurológica.", "Posições: decúbito lateral esquerdo (Bates) ou genupeitoral (Porto); decúbito dorsal semissentado apenas para pacientes graves.", "Comunicação obrigatória: avisar sobre pressão, umidade e frio do lubrificante e sensação falsa de evacuar ou urinar; garantir micção prévia."]}, {"t": "Técnica do toque retal (slide 58)", "sub": ["1) Inspeção perianal antes de tocar. 2) Apoiar a polpa do dedo no esfíncter e aguardar o relaxamento. 3) Introduzir o dedo em direção ao umbigo. 4) Avaliar o tônus esfincteriano e a ampola retal. 5) Varredura: rotação do dedo para palpar a face posterior da próstata. 6) Inspecionar a luva ao retirar (sangue, muco, fezes)."]}, {"t": "Como descrever a próstata (slide 59)", "sub": ["Apenas a face posterior é acessível; o lobo mediano é inacessível.", "Checklist: tamanho (normal cerca de 2,5 cm), forma e simetria (formato de coração), superfície (lisa ou irregular), consistência (elástica ou pétrea), sulco mediano (preservado ou apagado), mobilidade (fixa ou móvel) e dor."]}, {"t": "Padrões ao toque (slide 61)", "sub": ["Normal: elástica, lisa e simétrica, sulco presente, sem dor.", "HPB: firme, discretamente elástica, lisa, simétrica e aumentada; sulco pode apagar; sem dor.", "Prostatite aguda: amolecida, pastosa, quente, aumentada e edemaciada; dor intensa.", "Câncer: nódulo duro com evolução para consistência pétrea; irregular, assimétrica, fixa; sulco apagado; dor habitualmente ausente.", "Alerta: na prostatite aguda, examine com extrema delicadeza. O toque normal não exclui câncer; nódulo duro sempre exige investigação; o rastreio com PSA exige decisão compartilhada."]}]}, {"titulo": "7. Escroto agudo e urgências (slides 64 a 75)", "pontos": [{"t": "Torção, epididimite ou orquite? (slide 65)", "sub": ["Torção testicular (emergência cirúrgica): início súbito, dor lancinante; recém-nascidos e adolescentes; testículo elevado e horizontalizado (sinal de Brunzel); reflexo cremastérico ausente; epidídimo não individualizado; sem sintomas urinários.", "Epididimite aguda: início agudo e progressivo; jovens (IST: gonococo, Chlamydia) e idosos (gram-negativos); epidídimo aumentado, endurecido e muito doloroso; sintomas urinários possíveis; reflexo cremastérico presente.", "Orquite aguda: início súbito com febre alta; pacientes com caxumba e outras viroses; testículo edemaciado, escroto avermelhado, náuseas e vômitos; elevação manual reduz a dor (sinal de Prehn).", "Torção do apêndice testicular: agudo ou subagudo; escolares de 7 a 12 anos; testículo em posição normal; reflexo cremastérico presente; sem sintomas urinários.", "Caso J., 16 anos: torção intermitente; a pergunta decisiva é quanto tempo, e o encaminhamento cirúrgico é imediato."]}, {"t": "Reflexo cremastérico (slide 67)", "sub": ["Paciente em decúbito dorsal; tocar ou pinçar levemente a face superomedial da coxa.", "Resposta normal: elevação ipsilateral do testículo (raízes L1 a L2). Na torção, quase sempre ausente no lado afetado.", "Ressalva: avaliação difícil sob dor intensa. Reflexo presente sugere, mas não exclui torção."]}, {"t": "Sinal de Prehn (slide 68)", "sub": ["Elevar delicadamente o testículo doloroso em direção ao anel inguinal, com o paciente deitado.", "Prehn positivo (a dor alivia): sugere epididimite aguda ou orquite. Prehn negativo (não alivia ou piora): pensar em torção.", "Erro comum: baixa confiabilidade; não afasta torção, não substitui o Doppler e não deve atrasar a cirurgia."]}, {"t": "Sinal de Brunzel (slide 69)", "sub": ["Inspeção comparativa, em pé e deitado: o testículo afetado está visivelmente mais elevado, por encurtamento do cordão e espasmo grave do cremaster; perde a verticalidade e assume eixo horizontal.", "Atenção: examine o lado sadio; a deformidade em badalo de sino é bilateral em até 80% dos casos."]}, {"t": "Sinal do ponto azul: torção da hidátide de Morgagni (slide 70)", "sub": ["Torção isolada do apêndice testicular: dor pontual restrita ao polo superior e ponto azulado ou necrótico visível por transparência na pele esticada.", "Edema escrotal e pigmentação da pele reduzem a sensibilidade do sinal.", "Na dúvida entre torção de apêndice e torção do testículo, conduzir imediatamente como torção testicular."]}, {"t": "Manobra de Chevassu (slide 72)", "sub": ["Técnica: pinçar o epidídimo entre indicador e polegar, deslizando de baixo para cima e da frente para trás ao longo das faces do testículo.", "Aumento regular e difuso: sugere epididimite aguda. Irregular ou multinodular: sugere tuberculose genitourinária. Localizado: cistos (cabeça ou corpo) ou lesões inespecíficas (cauda).", "Objetivo: separar topograficamente a patologia do epidídimo das afecções primárias do testículo."]}, {"t": "Distorção manual e janela de salvamento (slide 73)", "sub": ["Distorção manual ('abrir o livro'): girar de medial para lateral; frequentemente exige mais de 360 graus de rotação. Sucesso: alívio da dor e retorno do fluxo ao Doppler.", "Medida temporária emergencial: nunca substitui a exploração cirúrgica definitiva.", "Janela de salvamento: menos de 6 horas, 90 a 100%; mais de 12 horas, cerca de 50%; mais de 24 horas, menos de 10%."]}, {"t": "Escore TWIST (slides 74 e 75)", "sub": ["Edema testicular intenso: 2 pontos. Testículo palpavelmente endurecido: 2 pontos. Reflexo cremastérico ausente: 1 ponto. Náuseas ou vômitos: 1 ponto. Testículo elevado (Brunzel): 1 ponto.", "Alto risco (5 a 7): avaliação cirúrgica urológica imediata; o Doppler não deve atrasar a cirurgia. Risco intermediário (3 a 4): ultrassonografia com Doppler imediata. Baixo risco (0 a 2): avaliar diagnósticos alternativos.", "Escore validado em populações pediátricas e adolescentes; otimiza o tempo porta-centro cirúrgico."]}]}, {"titulo": "8. Integração, erros comuns, roteiro e registro (slides 76 a 82)", "pontos": [{"t": "Mapeamento de urgências (slide 77)", "sub": ["Parafimose, torção testicular, hérnia estrangulada, prostatite aguda com retenção e priapismo são urgências que custam órgãos ou vidas se não diagnosticadas de imediato."]}, {"t": "Erros comuns do aluno (slide 78)", "sub": ["O slide lista como erro pesquisar varicocele e hérnia inguinal exclusivamente com o paciente deitado, porque as varicoceles colapsam em decúbito: a pesquisa correta é em pé (confirmado pelo roteiro do slide 81)."]}, {"t": "Roteiro do exame físico (slides 80 e 81)", "sub": ["Preparo: explicar e pedir consentimento; acompanhante se indicado; luvas; exposição mínima; avisar que a ereção reflexa é normal.", "Pênis: retrair o prepúcio e sempre devolvê-lo; comprimir a glande para abrir o meato; palpar o corpo; ordenhar a uretra se houver secreção; placa dorsal (Peyronie), induração ventral (estenose ou carcinoma).", "Massa escrotal: cinco perguntas. Em pé: varicocele (funículo 2 cm acima do testículo, Valsalva) e hérnias (invaginar a pele escrotal até o anel superficial e pedir tosse); palpar medial à artéria femoral; hérnia irredutível e dolorosa sugere estrangulamento."]}, {"t": "Como registrar o exame normal e o caso A. (slides 79 e 82)", "sub": ["Descreva o que viu e palpou, por segmento e na ordem do exame; hipóteses diagnósticas não entram no exame físico; o que não foi descrito não existe para o próximo médico.", "Normal: pênis sem lesões ou secreção, prepúcio retrátil; testículos tópicos, ovoides, elásticos, indolores, sem nódulos; epidídimos sem alterações; sem hérnias (em pé, com tosse); esfíncter normotônico, próstata simétrica, elástica, lisa, indolor e móvel, com sulco mediano presente.", "Caso A., 68 anos: esfíncter normotônico; próstata assimétrica com nódulo duro de 1 cm no lobo esquerdo, indolor, sulco apagado."]}]}], "glossario": [{"termo": "Esmegma", "epônimo": "", "tecnica": "Inspeção do prepúcio retraído", "definicao": "Material caseoso fisiológico sob o prepúcio; devolver sempre o prepúcio após a inspeção.", "slide": 6}, {"termo": "Cancro duro e cancro mole", "epônimo": "", "tecnica": "Úlceras genitais: dor e linfonodos", "definicao": "Sífilis primária: úlcera única indolor com bordas endurecidas e linfonodos firmes e indolores. Cancroide: úlcera dolorosa de base suja com bubões supurativos.", "slide": 29}, {"termo": "Doença de Peyronie", "epônimo": "Peyronie", "tecnica": "Palpação da placa no dorso do pênis", "definicao": "Placa fibrótica endurecida no dorso do pênis, que pode causar curvatura.", "slide": 33}, {"termo": "Síndrome de Klinefelter", "epônimo": "Klinefelter", "tecnica": "Medida do testículo", "definicao": "Testículo pequeno e firme, menor que 2 cm.", "slide": 40}, {"termo": "Manobra de Valsalva (varicocele)", "epônimo": "Valsalva", "tecnica": "Em pé, esforço expiratório com a glote fechada enquanto se palpa o funículo", "definicao": "Aumenta o diâmetro venoso: saco de vermes que colapsa em decúbito. Classificação tipos I a III.", "slide": 47}, {"termo": "Reflexo cremastérico", "epônimo": "", "tecnica": "Tocar a face superomedial da coxa", "definicao": "Elevação do testículo ipsilateral (L1 a L2); ausente na torção, mas reflexo presente não a exclui.", "slide": 67}, {"termo": "Sinal de Prehn", "epônimo": "Prehn", "tecnica": "Elevar o testículo doloroso em direção ao anel inguinal, em decúbito", "definicao": "Alívio da dor sugere epididimite ou orquite; sem alívio, pensar em torção. Baixa confiabilidade.", "slide": 68}, {"termo": "Sinal de Brunzel", "epônimo": "Brunzel", "tecnica": "Inspeção comparativa, em pé e deitado", "definicao": "Testículo afetado visivelmente mais elevado e horizontalizado, por encurtamento do cordão e espasmo do cremaster; sugere torção.", "slide": 69}, {"termo": "Sinal do ponto azul (hidátide de Morgagni)", "epônimo": "Morgagni", "tecnica": "Inspeção do polo superior do testículo", "definicao": "Ponto azulado ou necrótico por transparência na torção do apêndice testicular; na dúvida, conduzir como torção testicular.", "slide": 70}, {"termo": "Manobra de Chevassu", "epônimo": "Chevassu", "tecnica": "Pinçar o epidídimo entre indicador e polegar, deslizando de baixo para cima e de frente para trás", "definicao": "Isola o epidídimo: aumento regular sugere epididimite aguda; irregular ou multinodular, tuberculose; localizado, cistos ou lesões inespecíficas.", "slide": 72}, {"termo": "Distorção manual (abrir o livro)", "epônimo": "", "tecnica": "Giro do testículo de medial para lateral, às vezes mais de 360 graus", "definicao": "Medida temporária na torção; sucesso é alívio da dor e retorno do fluxo ao Doppler; não substitui a cirurgia.", "slide": 73}, {"termo": "Escore TWIST", "epônimo": "TWIST", "tecnica": "Pontuação clínica do escroto agudo", "definicao": "Edema testicular intenso e testículo endurecido (2 pontos cada); cremastérico ausente, náuseas ou vômitos e testículo elevado (1 ponto cada). Alto risco 5 a 7: cirurgia imediata.", "slide": 74}], "manobras": [{"nome": "Ordenha uretral", "epônimo": null, "como": "Expressão firme da base do pênis até a glande.", "alterado": "Secreção uretral.", "significado": "Fundamental se há queixa de secreção não visível em repouso; Gram e cultura confirmam a etiologia.", "slide": 32}, {"nome": "Compressão suave da glande", "epônimo": null, "como": "Comprimir a glande para abrir o meato uretral e inspecionar.", "alterado": "Estenose, secreção, posição anômala do meato.", "significado": "Estenose de meato, hipospádia, uretrite.", "slide": 33}, {"nome": "Palpação do testículo e do epidídimo (unimanual)", "epônimo": null, "como": "Palpar entre polegar e dois dedos, sem apertar, sempre comparando os lados.", "alterado": "Nódulo duro e indolor; epidídimo doloroso.", "significado": "Nódulo duro é câncer até prova em contrário; epididimite pela dor.", "slide": 37}, {"nome": "Palpar acima da massa escrotal", "epônimo": null, "como": "Tentar palpar a alça acima da massa, em direção ao anel.", "alterado": "Dedos conseguem palpar acima.", "significado": "Hidrocele; hérnia escrotal não permite.", "slide": 44}, {"nome": "Toque retal: técnica passo a passo", "epônimo": null, "como": "Inspecionar a região perianal; apoiar a polpa do dedo e aguardar o relaxamento; introduzir em direção ao umbigo; avaliar tônus e ampola; girar o dedo para a face posterior da próstata; inspecionar a luva.", "alterado": "Tônus alterado, massa na ampola, nódulo, assimetria ou dor.", "significado": "Triagem prostática; o toque normal não exclui câncer; nódulo duro exige investigação urológica.", "slide": 57}, {"nome": "Toque retal (técnica estruturada)", "epônimo": null, "como": "Decúbito lateral esquerdo ou genupeitoral; apoiar e esperar relaxamento; introduzir em direção ao umbigo; girar o dedo.", "alterado": "Tônus alterado, massa na ampola, nódulo ou assimetria prostática.", "significado": "Triagem prostática; nódulo duro exige investigação urológica.", "slide": 58}, {"nome": "Reflexo cremastérico", "epônimo": null, "como": "Paciente em decúbito dorsal; tocar ou pinçar levemente a face superomedial da coxa e observar o testículo do mesmo lado.", "alterado": "Ausência de elevação ipsilateral.", "significado": "Na torção, quase sempre ausente (raízes L1 a L2); reflexo presente sugere, mas não exclui torção.", "slide": 67}, {"nome": "Sinal de Prehn", "epônimo": "Prehn", "como": "Elevar delicadamente o testículo em direção ao anel inguinal, em decúbito.", "alterado": "Dor não alivia.", "significado": "Pensar em torção (baixa confiabilidade).", "slide": 68}, {"nome": "Sinal de Brunzel", "epônimo": "Brunzel", "como": "Inspeção visual comparativa, com o paciente em pé e deitado.", "alterado": "Testículo afetado mais elevado, com eixo horizontal.", "significado": "Sugere torção testicular; examine o lado sadio, pois a deformidade em badalo de sino é bilateral em até 80%.", "slide": 69}, {"nome": "Sinal do ponto azul", "epônimo": "Morgagni", "como": "Inspeção do polo superior do testículo com a pele esticada.", "alterado": "Ponto azulado ou necrótico visível por transparência.", "significado": "Torção da hidátide de Morgagni; na dúvida, conduzir como torção testicular.", "slide": 70}, {"nome": "Transiluminação do escroto", "epônimo": null, "como": "Sala escura; lanterna de foco direto atrás do escroto.", "alterado": "Brilho vermelho (transilumina) ou sombra opaca (não transilumina).", "significado": "Transilumina: massa cística (hidrocele, cisto de epidídimo). Não transilumina: massa sólida (tumor, orquiepididimite, torção, hematocele, maioria das hérnias). Hidrocele irredutível no anel pode ser indistinguível de hérnia estrangulada.", "slide": 71}, {"nome": "Manobra de Chevassu", "epônimo": "Chevassu", "como": "Pinçar o epidídimo entre indicador e polegar, deslizando de baixo para cima e de frente para trás ao longo das faces do testículo.", "alterado": "Aumento regular e difuso; irregular e multinodular; localizado.", "significado": "Regular e difuso: epididimite aguda. Irregular ou multinodular: tuberculose genitourinária. Localizado: cistos (cabeça ou corpo) ou lesões inespecíficas (cauda).", "slide": 72}, {"nome": "Distorção manual do testículo", "epônimo": null, "como": "Girar o testículo de medial para lateral (abrir o livro), muitas vezes mais de 360 graus.", "alterado": "Alívio da dor e retorno do fluxo ao Doppler.", "significado": "Medida temporária de emergência na torção.", "slide": 73}, {"nome": "Escore TWIST", "epônimo": "TWIST", "como": "Somar: edema testicular intenso (2), testículo endurecido (2), cremastérico ausente (1), náuseas ou vômitos (1), testículo elevado (1).", "alterado": "5 a 7 pontos, alto risco; 3 a 4, intermediário; 0 a 2, baixo.", "significado": "Alto risco: cirurgia imediata, sem atrasar pelo Doppler; intermediário: Doppler imediato; baixo: diagnósticos alternativos.", "slide": 74}, {"nome": "Retração e devolução do prepúcio", "epônimo": null, "como": "Retrair o prepúcio para inspecionar a glande; devolver SEMPRE em seguida.", "alterado": "Prepúcio que não retorna e edema da glande.", "significado": "Parafimose, urgência.", "slide": 78}, {"nome": "Palpação do corpo do pênis e ordenha uretral", "epônimo": null, "como": "Palpar o corpo entre polegar e dois dedos; ordenhar a uretra se houver queixa de secreção.", "alterado": "Placa dorsal, induração ventral, secreção.", "significado": "Peyronie; estenose ou carcinoma; uretrite.", "slide": 80}, {"nome": "Pesquisa de hérnia inguinal (em pé, com tosse)", "epônimo": null, "como": "Invaginar a pele escrotal até o anel inguinal superficial; pedir tosse.", "alterado": "Impulso contra o dedo.", "significado": "Hérnia inguinal indireta, direta; femoral pela palpação medial à artéria femoral.", "slide": 81}, {"nome": "Varicocele em pé com Valsalva", "epônimo": "Valsalva", "como": "Em pé, palpar o funículo cerca de 2 cm acima do testículo com Valsalva.", "alterado": "Saco de vermes que não colapsa.", "significado": "Varicocele; investigar se não colapsa ou surge após os 40 anos.", "slide": 81}], "caso": {"titulo": "Casos integradores de semiologia genitourinária masculina", "perfil": "Escroto agudo, reflexo cremastérico e TWIST, massa escrotal, varicocele, hérnias, parafimose, próstata e úlcera genital.", "etapas": [{"titulo": "Etapa 1 · J., 16 anos: dor escrotal súbita (slides 3 e 65)", "texto": "J., 16 anos, chega com dor escrotal esquerda súbita há 2 horas, com náusea. Teve um episódio semelhante meses antes que cedeu sozinho. Ao exame, o testículo esquerdo está elevado e horizontalizado, o reflexo cremastérico está ausente à esquerda, e não há febre nem sintomas urinários.", "perguntas": [{"pergunta": "Qual é a hipótese diagnóstica e o que a diferencia da epididimite?", "alternativas": ["Torção: início súbito, testículo elevado, sem sintomas urinários", "Epididimite aguda: início progressivo, febre e sintomas urinários", "Orquite viral: febre alta, caxumba e testículo edemaciado", "Hidrocele: massa indolor, cística, que transilumina bem", "Hérnia escrotal: massa em que não se palpa acima dela"], "gabarito": "A", "justificativa": "Início súbito e lancinante em adolescente, testículo elevado e horizontalizado (Brunzel), cremastérico ausente e sem sintomas urinários caracterizam a torção testicular.", "erradas": {"B": "A epididimite é progressiva, com sintomas urinários e cremastérico presente.", "C": "A orquite cursa com febre alta e geralmente cremastérico presente.", "D": "A hidrocele é indolor e transilumina.", "E": "A hérnia escrotal não explica dor súbita com testículo elevado."}}, {"pergunta": "Qual é a pergunta decisiva à beira do leito e a conduta?", "alternativas": ["Qual doença é? Aguardar urina e ultrassom em 24 horas", "Quanto tempo? Encaminhar para cirurgia imediata", "Há febre? Prescrever antibiótico e reavaliar em 7 dias", "Há histórico familiar? Marcar consulta eletiva", "Há dor ao urinar? Iniciar analgesia e observar"], "gabarito": "B", "justificativa": "A pergunta decisiva não é qual doença, e sim quanto tempo; o encaminhamento cirúrgico é imediato, pois o salvamento testicular depende do tempo.", "erradas": {"A": "Aguardar 24 horas reduz o salvamento para menos de 10%.", "C": "Antibiótico e reavaliação não tratam torção.", "D": "Consulta eletiva não é compatível com emergência.", "E": "Analgesia e observação atrasam a cirurgia."}}]}, {"titulo": "Etapa 2 · Reflexo cremastérico e sinal de Prehn (slides 67 e 68)", "texto": "No pronto atendimento, o residente testa o reflexo cremastérico e encontra reflexo presente à esquerda. Em seguida, eleva o testículo doloroso e a dor não alivia. Ele conclui: 'reflexo presente, então não é torção'.", "perguntas": [{"pergunta": "Como interpretar o reflexo cremastérico presente?", "alternativas": ["Exclui torção, pois o arco reflexo L1-L2 está íntegro", "Sugere, mas não exclui torção; ausência é a regra", "Confirma epididimite, pois só ocorre nessa doença aguda", "Confirma orquite viral, pelo reflexo preservado e febre", "Indica torção do apêndice em todos os casos de dor"], "gabarito": "B", "justificativa": "Na torção o reflexo é quase sempre ausente, mas um reflexo presente sugere sem excluir torção; não deve desviar a conduta.", "erradas": {"A": "O reflexo presente não exclui torção.", "C": "Reflexo presente não confirma epididimite isoladamente.", "D": "Reflexo presente não confirma orquite isoladamente.", "E": "A presença do reflexo ocorre também na torção do apêndice, mas não é exclusiva."}}, {"pergunta": "O que significa Prehn sem alívio da dor e qual é sua limitação?", "alternativas": ["Sugere epididimite, com sinal altamente confiável e definitivo", "Sugere torção, tem baixa confiabilidade e não atrasa cirurgia", "Confirma torção e dispensa qualquer exame complementar", "Sugere hidrocele e dispensa o exame físico completo", "Sugere hérnia estrangulada e exige redução manual imediata"], "gabarito": "B", "justificativa": "Prehn negativo (a dor não alivia) sugere torção; o sinal tem baixa confiabilidade, não afasta nem confirma torção sozinho e não deve atrasar a cirurgia.", "erradas": {"A": "O alívio da dor sugere epididimite, e o sinal tem baixa confiabilidade.", "C": "Prehn não confirma torção isoladamente.", "D": "Prehn não avalia hidrocele.", "E": "Prehn não avalia hérnia."}}]}, {"titulo": "Etapa 3 · Escore TWIST e janela de salvamento (slides 73 e 74)", "texto": "Outro adolescente tem edema testicular intenso, testículo endurecido à palpação, reflexo cremastérico ausente, náuseas e testículo elevado, com 4 horas de dor. O urologista está a 30 minutos; o ultrassom com Doppler só estará disponível em 2 horas.", "perguntas": [{"pergunta": "Qual é o escore TWIST e a conduta indicada?", "alternativas": ["7 pontos: alto risco, cirurgia imediata sem esperar o Doppler", "3 pontos: risco intermediário, Doppler e alta se normal", "2 pontos: baixo risco, avaliar diagnósticos alternativos", "7 pontos: alto risco, porém aguardar o Doppler antes da cirurgia", "0 pontos: baixo risco, reavaliar em 24 horas de observação"], "gabarito": "A", "justificativa": "Edema intenso (2) mais endurecimento (2) mais cremastérico ausente (1) mais náuseas (1) mais testículo elevado (1) somam 7; escore de 5 a 7 é de alto risco e o Doppler não deve atrasar a cirurgia.", "erradas": {"B": "O escore de 3 a 4 corresponde a risco intermediário.", "C": "O escore de 0 a 2 é de baixo risco.", "D": "Em alto risco, o Doppler não deve atrasar a cirurgia.", "E": "Esperar 24 horas reduz o salvamento para menos de 10%."}}, {"pergunta": "Enquanto aguarda a cirurgia, qual medida é correta e qual é sua limitação?", "alternativas": ["Distorção manual, medial para lateral; não substitui cirurgia", "Compressão do cordão; substitui a cirurgia se houver alívio", "Antibiótico oral de amplo espectro por sete dias; trata torção", "Gelo local por uma hora; evita a necessidade de cirurgia", "Elevação do escroto por 1 hora; resolve a torção testicular"], "gabarito": "A", "justificativa": "A distorção manual (abrir o livro), de medial para lateral, exige muitas vezes mais de 360 graus; sucesso é alívio e retorno do fluxo ao Doppler, mas é medida temporária que nunca substitui a exploração cirúrgica.", "erradas": {"B": "Compressão do cordão não é a manobra descrita.", "C": "Antibiótico não trata torção.", "D": "Gelo local não evita a cirurgia.", "E": "A elevação isolada não resolve a torção."}}]}, {"titulo": "Etapa 4 · Massa escrotal (slides 43 e 71)", "texto": "Homem de 35 anos tem massa escrotal direita indolor, de crescimento lento. Ao exame, o examinador consegue palpar acima da massa; a lanterna atrás do escroto produz brilho vermelho; o testículo é palpável e separado; a massa não reduz.", "perguntas": [{"pergunta": "Qual é o diagnóstico mais provável?", "alternativas": ["Hérnia escrotal, pois não se palpa acima da massa", "Tumor testicular, pois a massa sólida não transilumina", "Hidrocele, pois palpa acima e a massa transilumina", "Varicocele, pois a massa reduz ao deitar o paciente", "Torção testicular, pela dor súbita intensa e náuseas"], "gabarito": "C", "justificativa": "Palpar acima da massa e transiluminação positiva (brilho vermelho) indicam massa cística confinada ao escroto, como hidrocele.", "erradas": {"A": "Na hérnia não se palpa acima da massa.", "B": "Tumor sólido não transilumina, e aqui há brilho vermelho.", "D": "Varicocele não transilumina e reduz em decúbito.", "E": "A massa é indolor e de crescimento lento, e não súbita."}}, {"pergunta": "Qual armadilha a transiluminação pode esconder?", "alternativas": ["Tumor sólido que transilumina em toda a sua extensão ao exame", "Hidrocele irredutível no anel transilumina e simula hérnia", "Varicocele que transilumina e colapsa ao deitar o paciente", "Torção testicular que transilumina com brilho vermelho intenso", "Epididimite aguda que transilumina com brilho vermelho"], "gabarito": "B", "justificativa": "Hidrocele irredutível no anel inguinal transilumina, mas pode ser clinicamente indistinguível de hérnia estrangulada.", "erradas": {"A": "Tumor sólido não transilumina.", "C": "A varicocele não transilumina.", "D": "A torção é massa sólida e não transilumina.", "E": "A epididimite não é massa cística."}}]}, {"titulo": "Etapa 5 · Varicocele e hérnia em pé (slides 46, 48 e 50)", "texto": "Homem de 42 anos, em pé, tem massa à esquerda que, ao Valsalva, aumenta e tem consistência de saco de vermes acima e atrás do testículo. Ao deitar, não colapsa. Em outro exame, o indicador invagina a pele escrotal até o anel superficial e toca a ponta do dedo na tosse.", "perguntas": [{"pergunta": "Qual é o significado de varicocele que não colapsa deitado?", "alternativas": ["Normal, pois a varicocele nunca colapsa ao deitar", "Exige investigação por compressão retroperitoneal", "Confirma hidrocele associada ao mesmo lado esquerdo", "Indica torção do cordão espermático com isquemia", "Indica hérnia direta no canal inguinal esquerdo"], "gabarito": "B", "justificativa": "Varicocele que não colapsa em decúbito ou que surge subitamente após os 40 anos exige investigação por possível compressão retroperitoneal.", "erradas": {"A": "A varicocele típica colapsa em decúbito.", "C": "A hidrocele não é a explicação.", "D": "A torção cursa com dor súbita.", "E": "A hérnia não explica o saco de vermes."}}, {"pergunta": "Qual hérnia toca a ponta do dedo na tosse e desce ao escroto?", "alternativas": ["Direta, que se origina na parede posterior do canal", "Indireta, que se origina no anel inguinal profundo", "Femoral, que se origina abaixo do ligamento inguinal", "Umbilical, que se origina na cicatriz umbilical", "Epigástrica, que se origina na linha alba superior"], "gabarito": "B", "justificativa": "A hérnia indireta é a mais frequente, origina-se no anel profundo, desce ao escroto e toca a ponta do dedo na tosse; a direta toca a polpa e raramente desce.", "erradas": {"A": "A direta toca a polpa do dedo e raramente vai ao escroto.", "C": "A femoral nunca vai ao escroto no homem.", "D": "A umbilical não é inguinal.", "E": "A epigástrica não é inguinal."}}]}, {"titulo": "Etapa 6 · Parafimose e hérnia estrangulada (slides 6 e 50)", "texto": "Um paciente chega com prepúcio retraído, que não consegue devolver, e glande edemaciada e dolorosa. Outro tem massa inguinal irredutível, dolorosa, com vômitos.", "perguntas": [{"pergunta": "Qual é o diagnóstico e a prioridade de cada um?", "alternativas": ["Fimose e hérnia redutível; ambulatório eletivo de rotina", "Parafimose e estrangulamento herniário; emergências", "Balanite e hidrocele; antibiótico oral e retorno em 7 dias", "Hipospádia e varicocele; observação clínica sem urgência", "Esmegma e hérnia direta; alta com orientação geral"], "gabarito": "B", "justificativa": "Prepúcio retraído que não retorna e edemacia a glande é parafimose (urgência); massa irredutível e dolorosa com vômitos é estrangulamento (emergência cirúrgica).", "erradas": {"A": "Fimose é incapacidade de retrair, e a hérnia irredutível não é redutível.", "C": "Balanite e hidrocele não explicam os quadros.", "D": "Hipospádia é congênita e varicocele não é irredutível.", "E": "Esmegma é fisiológico e hérnia irredutível dolorosa exige urgência."}}]}, {"titulo": "Etapa 7 · A., 68 anos, noctúria e próstata (slides 3, 59, 61 e 79)", "texto": "A., 68 anos, tem noctúria de 4 episódios, jato fraco e esforço para urinar. Ao toque retal, esfíncter normotônico; a próstata é assimétrica, com nódulo duro de 1 cm no lobo esquerdo, indolor, com sulco mediano apagado.", "perguntas": [{"pergunta": "Qual é a interpretação do toque e a conduta?", "alternativas": ["HPB típica, simétrica e lisa: observar e retornar em um ano", "Nódulo duro exige investigação urológica imediata", "Prostatite aguda: realizar massagem prostática vigorosa", "Exame normal: apenas orientar higiene e hidratação", "Abscesso prostático: drenagem cirúrgica imediata hoje"], "gabarito": "B", "justificativa": "Nódulo duro, assimétrico e com sulco apagado exige investigação urológica; na HPB a próstata é simétrica e firme, e o rastreio com PSA exige decisão compartilhada.", "erradas": {"A": "A HPB é simétrica e lisa.", "C": "Na prostatite aguda examina-se com delicadeza, sem massagem vigorosa.", "D": "O achado não é normal.", "E": "Não há dado de abscesso."}}, {"pergunta": "Como esse achado seria registrado no prontuário, segundo a regra de ouro?", "alternativas": ["Câncer de próstata, com nódulo duro no lobo esquerdo e sulco apagado", "Próstata assimétrica, nódulo duro de 1 cm à esquerda, sulco apagado", "Próstata anormal, com suspeita de malignidade, nódulo e sulco apagado", "Toque retal positivo para câncer, com nódulo duro e sulco apagado", "Sem alterações relevantes ao toque, exceto sulco apagado isolado"], "gabarito": "B", "justificativa": "Hipóteses diagnósticas não entram no exame físico; descreve-se o que se viu e palpou: tônus, simetria, nódulo, tamanho, lado, dor e sulco.", "erradas": {"A": "Câncer de próstata é hipótese, e não achado.", "C": "Anormal e suspeita são termos vagos.", "D": "Positivo para câncer é interpretação.", "E": "A frase omite o nódulo e o sulco apagado."}}]}, {"titulo": "Etapa 8 · Úlcera genital (slide 29)", "texto": "Homem de 27 anos apresenta úlcera única de 1 cm na glande, indolor, de base limpa e bordas endurecidas, com linfonodos inguinais firmes e indolores. Há uma semana teve relação desprotegida.", "perguntas": [{"pergunta": "Qual é o diagnóstico mais provável?", "alternativas": ["Herpes genital, por vesículas agrupadas dolorosas", "Sífilis primária (cancro duro), por úlcera indolor firme", "Cancroide, por úlcera profunda e dolorosa com bubões", "Condiloma acuminado, por lesão verrucosa em couve-flor", "Balanite candidiásica, por placas esbranquiçadas e prurido"], "gabarito": "B", "justificativa": "Úlcera única indolor, de base limpa e bordas endurecidas, com linfonodos indolores e firmes, é sífilis primária (cancro duro).", "erradas": {"A": "O herpes é doloroso, com vesículas agrupadas.", "C": "O cancroide é doloroso, com base suja e bubões.", "D": "O condiloma é verrucoso.", "E": "A balanite candidiásica não forma úlcera de bordas endurecidas."}}]}]}, "imagens": [{"slide": 2, "titulo": "Semiologia do GU masculino", "explicacao": "Regra de ouro: descrever os achados antes de nomear a doença; sequência pênis, escroto, inguinal, próstata.", "arquivo": "img/aula-09/slide-02.jpg"}, {"slide": 4, "titulo": "Sequência do exame genitourinário", "explicacao": "Anamnese, pênis, escroto, região inguinal, próstata e registro.", "arquivo": "img/aula-09/slide-04.jpg"}, {"slide": 6, "titulo": "Pênis e uretra: o que se inspeciona", "explicacao": "Corpos cavernosos, prepúcio, meato; parafimose é urgência.", "arquivo": "img/aula-09/slide-06.jpg"}, {"slide": 8, "titulo": "Escroto e testículo: o que se palpa", "explicacao": "Testículo, epidídimo, túnica vaginal; nódulo duro indolor é câncer até prova em contrário.", "arquivo": "img/aula-09/slide-08.jpg"}, {"slide": 10, "titulo": "Anatomia que muda o raciocínio", "explicacao": "Varicocele à esquerda pela veia renal; drenagem linfática do testículo e do pênis.", "arquivo": "img/aula-09/slide-10.jpg"}, {"slide": 11, "titulo": "Região inguinal e canal femoral", "explicacao": "Ligamento inguinal como divisor; hérnia inguinal e femoral.", "arquivo": "img/aula-09/slide-11.jpg"}, {"slide": 13, "titulo": "Próstata: o que o dedo alcança", "explicacao": "Só a face posterior é palpável; nódulo duro exige investigação.", "arquivo": "img/aula-09/slide-13.jpg"}, {"slide": 15, "titulo": "Anatomia aplicada ao exame", "explicacao": "Pênis, escroto, varicocele, drenagem linfática, região inguinal e próstata: o que o dedo alcança e a sequência do exame."}, {"slide": 17, "titulo": "Como perguntar sobre genitália e sexualidade", "explicacao": "Objetividade, explicar o porquê, pistas invisíveis (idade e risco ocupacional)."}, {"slide": 18, "titulo": "Sintomas urinários baixos (LUTS)", "explicacao": "Obstrutivos (esvaziamento) e irritativos (armazenamento)."}, {"slide": 19, "titulo": "Disúria, hematúria e febre", "explicacao": "Origem da hematúria e combinações; febre, disúria e dor perineal sugerem prostatite.", "arquivo": "img/aula-09/slide-19.jpg"}, {"slide": 20, "titulo": "Secreção uretral e lesões", "explicacao": "Características, achados locais e sistêmicos (tríade da artrite reativa); Gram e cultura confirmam."}, {"slide": 21, "titulo": "Escroto: dor e aumento de volume", "explicacao": "Cronologia insidiosa x súbita; torção é emergência.", "arquivo": "img/aula-09/slide-21.jpg"}, {"slide": 22, "titulo": "Função sexual e reprodutiva", "explicacao": "Vias da ereção, disfunção erétil, ejaculação, libido, infertilidade e priapismo."}, {"slide": 23, "titulo": "História sexual e risco de IST: os 5 Ps", "explicacao": "Parcerias, práticas, preservativo, passado de ISTs e prevenção."}, {"slide": 24, "titulo": "Anamnese dirigida: resumo e red flags", "explicacao": "Disúria, hematúria, secreção, escroto, função sexual, IST e sinais de alerta."}, {"slide": 26, "titulo": "Preparo e ética no exame genital", "explicacao": "Explicar, acompanhante, luvas, exposição mínima, posição e aviso sobre ereção reflexa."}, {"slide": 27, "titulo": "Inspeção do pênis", "explicacao": "Retrair e devolver o prepúcio; fimose, hipospádia e parafimose."}, {"slide": 28, "titulo": "Anomalias do meato", "explicacao": "Hipospádia e estenose de meato.", "arquivo": "img/aula-09/slide-28.jpg"}, {"slide": 29, "titulo": "Úlceras genitais: diagnóstico diferencial", "explicacao": "Sífilis, herpes, cancroide e condiloma, por dor, aspecto e linfonodos."}, {"slide": 30, "titulo": "Úlceras e verrugas genitais", "explicacao": "Condiloma, herpes, cancro e cancroide.", "arquivo": "img/aula-09/slide-30.jpg"}, {"slide": 32, "titulo": "Meato, ordenha uretral e corpo peniano", "explicacao": "Compressão da glande, ordenha e palpação; Peyronie versus estenose ou carcinoma."}, {"slide": 33, "titulo": "Meato e corpo do pênis", "explicacao": "Compressão da glande; placa de Peyronie.", "arquivo": "img/aula-09/slide-33.jpg"}, {"slide": 34, "titulo": "Inspeção do escroto e das regiões inguinais", "explicacao": "Levantar o escroto, criptorquidia e sentinelas sistêmicas."}, {"slide": 36, "titulo": "Palpação do testículo", "explicacao": "Unimanual e bimanual, seis parâmetros e alerta de nódulo indolor."}, {"slide": 37, "titulo": "Palpação do testículo", "explicacao": "Técnica unimanual e autoexame.", "arquivo": "img/aula-09/slide-37.jpg"}, {"slide": 38, "titulo": "Epidídimo e funículo", "explicacao": "Chevassu, deferente em corda de chicote, contas de rosário e funiculite."}, {"slide": 40, "titulo": "Testículo: variações de posição e tamanho", "explicacao": "Criptorquidia, ectopia, testículo retrátil e Klinefelter."}, {"slide": 41, "titulo": "Testículo fora do lugar ou do tamanho", "explicacao": "Ectopias, criptorquidia e testículo pequeno.", "arquivo": "img/aula-09/slide-41.jpg"}, {"slide": 43, "titulo": "Massa escrotal: as cinco perguntas", "explicacao": "Fluxograma: palpo acima, transilumina, reduz."}, {"slide": 44, "titulo": "Hidrocele x hérnia escrotal", "explicacao": "Os dedos passam acima da massa na hidrocele, não na hérnia.", "arquivo": "img/aula-09/slide-44.jpg"}, {"slide": 45, "titulo": "Hidrocele, cisto e tumor", "explicacao": "Diferencial de massa escrotal, incluindo tumor testicular.", "arquivo": "img/aula-09/slide-45.jpg"}, {"slide": 46, "titulo": "Varicocele: dinâmica de exame", "explicacao": "Valsalva, classificação I a III e alerta após os 40 anos."}, {"slide": 47, "titulo": "Varicocele", "explicacao": "Saco de vermes no funículo; aspecto externo e ultrassonografia.", "arquivo": "img/aula-09/slide-47.jpg"}, {"slide": 48, "titulo": "Pesquisa de hérnia inguinal", "explicacao": "Cinco passos com invaginação da pele escrotal e tosse."}, {"slide": 50, "titulo": "Hérnias da virilha", "explicacao": "Indireta, direta e femoral; estrangulamento."}, {"slide": 53, "titulo": "Exame do pênis, do escroto e da região inguinal", "explicacao": "Resumo das seis etapas e dos alertas vermelhos."}, {"slide": 55, "titulo": "Toque retal: preparo e posicionamento", "explicacao": "Decúbito lateral esquerdo (Bates), genupeitoral (Porto) e comunicação obrigatória."}, {"slide": 57, "titulo": "Técnica do toque retal", "explicacao": "Seis passos, da inspeção perianal à inspeção da luva."}, {"slide": 58, "titulo": "Técnica do toque retal", "explicacao": "Posição, introdução do dedo e palpação da superfície retal.", "arquivo": "img/aula-09/slide-58.jpg"}, {"slide": 59, "titulo": "Como descrever a próstata", "explicacao": "Checklist de registro: tamanho, forma, superfície, consistência, sulco, mobilidade e dor."}, {"slide": 61, "titulo": "Próstata normal, HPB, prostatite e câncer", "explicacao": "Quadro comparativo por consistência, superfície, sulco e dor."}, {"slide": 62, "titulo": "Padrões da próstata ao toque", "explicacao": "Normal, prostatite aguda, HPB e câncer.", "arquivo": "img/aula-09/slide-62.jpg"}, {"slide": 63, "titulo": "Toque retal e próstata: resumo", "explicacao": "Preparo, posições, técnica, parâmetros e alertas."}, {"slide": 65, "titulo": "Escroto agudo: torção, epididimite ou orquite?", "explicacao": "Início, faixa etária, exame físico e associações; retorno ao caso J."}, {"slide": 66, "titulo": "Escroto agudo", "explicacao": "Orquite, epididimite e torção.", "arquivo": "img/aula-09/slide-66.jpg"}, {"slide": 67, "titulo": "Reflexo cremastérico", "explicacao": "L1 a L2; ausente na torção; presente não exclui."}, {"slide": 68, "titulo": "Sinal de Prehn", "explicacao": "Alívio sugere epididimite; sem alívio, pensar em torção; baixa confiabilidade.", "arquivo": "img/aula-09/slide-68.jpg"}, {"slide": 69, "titulo": "Sinal de Brunzel", "explicacao": "Testículo elevado e horizontalizado; examine o lado sadio."}, {"slide": 70, "titulo": "Sinal do ponto azul", "explicacao": "Torção da hidátide de Morgagni; na dúvida, conduzir como torção testicular."}, {"slide": 71, "titulo": "Transiluminação", "explicacao": "Brilho vermelho (cístico) versus sombra opaca (sólido)."}, {"slide": 72, "titulo": "Manobra de Chevassu", "explicacao": "Isolamento palpatório do epidídimo."}, {"slide": 73, "titulo": "Janela de salvamento na torção", "explicacao": "Menos de 6 horas: 90 a 100%; mais de 24 horas: menos de 10%.", "arquivo": "img/aula-09/slide-73.jpg"}, {"slide": 74, "titulo": "Escore TWIST", "explicacao": "Pontuação e conduta por faixa de risco."}, {"slide": 75, "titulo": "Escroto agudo: sinais e manobras especiais", "explicacao": "Tabela diferencial, TWIST, sinais e alerta de tempo."}, {"slide": 78, "titulo": "Erros comuns do aluno", "explicacao": "Prepúcio, palpação incompleta, varicocele deitado, epidídimo e omissão.", "arquivo": "img/aula-09/slide-78.jpg"}, {"slide": 79, "titulo": "Registro em prontuário e caso A.", "explicacao": "Exame normal por segmento; próstata com nódulo duro de 1 cm no lobo esquerdo no caso A."}, {"slide": 80, "titulo": "Roteiro do exame físico (1/2)", "explicacao": "Pênis e escroto: preparo, inspeção, palpação e manobra de Chevassu.", "arquivo": "img/aula-09/slide-80.jpg"}, {"slide": 81, "titulo": "Roteiro do exame físico (2/2)", "explicacao": "Massas, varicocele com Valsalva, hérnias, escroto agudo e toque retal.", "arquivo": "img/aula-09/slide-81.jpg"}, {"slide": 82, "titulo": "Como registrar o exame normal", "explicacao": "Descrição por segmento, na ordem do exame.", "arquivo": "img/aula-09/slide-82.jpg"}], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Prepúcio retraído que não retorna e edemacia a glande. Qual é a condição e qual é a urgência?", "alternativas": ["Parafimose, com urgência para desfazer a constrição", "Fimose simples, com observação ambulatorial e higiene local", "Balanite leve, com antibiótico tópico por sete dias", "Esmegma fisiológico, sem necessidade de conduta", "Hipospadia distal, com correção eletiva programada"], "gabarito": "A", "justificativa": "Prepúcio retraído que não retorna e edemacia a glande é parafimose: urgência, pelo risco de isquemia.", "epônimo": null, "tecnica": "Parafimose", "slide": 6}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Por que a varicocele aparece predominantemente à esquerda?", "alternativas": ["O testículo esquerdo é mais pesado e comprime o cordão", "Veia testicular esquerda drena em ângulo para a veia renal", "O ducto deferente esquerdo é mais longo e mais tortuoso", "A artéria testicular esquerda é mais calibrosa que a direita", "O linfonodo inguinal esquerdo drena o testículo esquerdo"], "gabarito": "B", "justificativa": "A veia testicular esquerda drena em ângulo reto para a veia renal esquerda, com maior pressão venosa.", "epônimo": null, "tecnica": "Varicocele", "slide": 10}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um homem de 40 anos tem nódulo testicular indolor e aumento de volume. Qual é a conduta com a linfonodopatia inguinal ausente?", "alternativas": ["Observar por seis meses, pois a drenagem é inguinal e sem risco", "Descartar câncer, pois a ausência de linfonodo exclui tumor", "Afastar câncer, pois não causa linfonodopatia inguinal", "Tratar como orquite, pois a linfonodopatia é ausente", "Encaminhar apenas se houver febre associada ao quadro"], "gabarito": "C", "justificativa": "Testículos drenam para o retroperitônio; o câncer testicular primário não causa linfonodopatia inguinal, e o nódulo indolor exige investigação.", "epônimo": null, "tecnica": "Drenagem linfática", "slide": 10}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Nódulo duro e indolor no testículo de adulto jovem. Qual é a interpretação e a conduta inicial?", "alternativas": ["Epididimite crônica, com antibiótico de longo prazo", "Cisto de epidídimo, com controle clínico em seis meses", "Hidrocele simples, com observação por um ano e reavaliação", "Câncer de testículo até prova em contrário, com urologia", "Varicocele com saco de vermes, com drenagem e controle"], "gabarito": "D", "justificativa": "Nódulo endurecido e indolor no testículo é câncer até prova em contrário, com pico entre 15 e 34 anos (slide 8).", "epônimo": null, "tecnica": "Testículo", "slide": 8}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Hérnia femoral: onde ela é palpada e por qual técnica?", "alternativas": ["Lateral à espinha ilíaca, com paciente em pé e tosse", "Na face posterior da próstata, pelo toque retal", "Sobre o tubérculo púbico, com invaginação escrotal", "No meato uretral, com a glande comprimida", "Medial à artéria femoral, por palpação cega"], "gabarito": "E", "justificativa": "A hérnia femoral é pesquisada por palpação cega, medial à artéria femoral.", "epônimo": null, "tecnica": "Hérnia femoral", "slide": 11}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Hérnia inguinal irredutível, dolorosa e com pele avermelhada. Qual é a suspeita e a conduta?", "alternativas": ["Estrangulamento herniário, com urgência cirúrgica", "Hérnia redutível, com observação, cinta e retorno clínico", "Hidrocele com transluminação positiva, com alta", "Varicocele com saco de vermes, com exame eletivo", "Epididimite, com antibiótico oral e retorno em sete dias"], "gabarito": "A", "justificativa": "Hérnia irredutível e dolorosa sugere estrangulamento: urgência cirúrgica, e não observação ambulatorial.", "epônimo": null, "tecnica": "Hérnia", "slide": 81}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Ao pesquisar varicocele e hérnia, em qual posição o exame deve ser feito?", "alternativas": ["Exclusivamente deitado, pois a varicocele colapsa em decúbito", "Em pé, com Valsalva ou tosse, para revelar a varicocele", "Sentado, com pernas cruzadas e tronco inclinado para frente", "Em decúbito lateral esquerdo, como no toque retal", "Em posição ginecológica, com joelhos fletidos e apoio dos pés"], "gabarito": "B", "justificativa": "Varicocele e hérnia são pesquisadas em pé, com Valsalva ou tosse (slide 81). O slide 78 resume o colapso da varicocele em decúbito, que é teste complementar e não substitui a manobra em pé.", "epônimo": null, "tecnica": "Varicocele", "slide": 81}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Varicocele que não colapsa ao deitar ou que surge após os 40 anos. Qual é a conduta?", "alternativas": ["Observação, pois a varicocele é sempre benigna aqui", "Cirurgia imediata, sem nenhum exame de imagem prévio", "Investigação da causa, por compressão retroperitoneal", "Alta com repouso e elevação do escroto por alguns dias", "Antibiótico de amplo espectro por dez dias, em casa"], "gabarito": "C", "justificativa": "Varicocele que não colapsa em decúbito ou que surge após 40 anos exige investigação da causa.", "epônimo": null, "tecnica": "Varicocele", "slide": 81}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Sintoma urinário terminal, com disúria no final da micção. Qual é a topografia provável?", "alternativas": ["Rim, ureter ou bexiga acima do colo vesical, na fase total", "Próstata lateral, com dor retal e disúria no início", "Uretra anterior, com disúria no início do jato urinário", "Colo vesical e trígono, na parte final da micção", "Parede abdominal, com dor irradiada à virilha e flanco"], "gabarito": "D", "justificativa": "Sintoma terminal indica colo vesical e trígono; sintoma inicial indica uretra; total indica rim, ureter ou bexiga alta.", "epônimo": null, "tecnica": "Sintoma urinário", "slide": 19}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Para o toque retal, qual é a posição do paciente e a primeira etapa do exame?", "alternativas": ["Decúbito dorsal com joelhos fletidos, com introdução do dedo", "Sentado sobre a maca, com palpação lateral do reto", "Em pé com o tronco inclinado, com introdução sem observação", "Decúbito ventral, com o dedo sobre o ânus após a palpação", "Decúbito lateral esquerdo, com relaxamento prévio"], "gabarito": "E", "justificativa": "O toque retal é feito em decúbito lateral esquerdo: observação do ânus, relaxamento e só depois a introdução do dedo.", "epônimo": null, "tecnica": "Toque retal", "slide": 56}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Ao toque retal, qual é o achado de próstata normal?", "alternativas": ["Simétrica, elástica, lisa, indolor e com sulco mediano", "Consistência dura, com superfície irregular e dor intensa", "Lobos assimétricos, com nódulo fixo e sulco apagado", "Consistência pétrea, com dor à compressão lateral", "Volume aumentado com flutuação e calor local"], "gabarito": "A", "justificativa": "Próstata normal é simétrica, elástica, lisa, indolor, móvel, com sulco mediano palpável.", "epônimo": null, "tecnica": "Próstata", "slide": 82}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Sulco mediano apagado isolado ao toque retal. Qual é a interpretação mais precisa?", "alternativas": ["Câncer de próstata confirmado, com indicação de biópsia imediata", "Ocorre na hiperplasia benigna, sem confirmar câncer", "Prostatite aguda, com febre e dor à palpação da glândula", "Normalidade, pois o sulco mediano nunca se altera no exame", "Abscesso prostático, com flutuação e dor intensa à palpação"], "gabarito": "B", "justificativa": "O sulco apagado isolado ocorre na hiperplasia benigna; nódulo duro, área pétrea ou assimetria exigem investigação urológica.", "epônimo": null, "tecnica": "HPB", "slide": 13}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Placa fibrosa palpável no dorso do pênis, com curvatura durante a ereção. Qual é o diagnóstico?", "alternativas": ["Hipospadia distal, por meato ventral e jato desviado", "Parafimose, por constrição do prepúcio sobre a glande", "Doença de Peyronie, por placa no dorso do pênis", "Balanopostite, por secreção purulenta e prurido local", "Condiloma acuminado, por verruga na glande e na pele"], "gabarito": "C", "justificativa": "Doença de Peyronie é placa fibrosa no dorso do pênis, que pode causar curvatura.", "epônimo": null, "tecnica": "Peyronie", "slide": 33}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Massa escrotal dolorosa de início súbito em adolescente, com testículo alto e horizontal. Qual é a hipótese prioritária?", "alternativas": ["Epididimite, pela dor de início gradual e febre baixa", "Varicocele, pelo saco de vermes ao esforço em pé", "Hidrocele, por transluminação positiva e sem dor", "Torção testicular, que exige pensar nela de imediato", "Hérnia escrotal, pela redução manual sem dor"], "gabarito": "D", "justificativa": "Início súbito, dor e testículo alto e horizontal: pensar em torção testicular de imediato.", "epônimo": null, "tecnica": "Torção", "slide": 68}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Sinais de alarme em escroto agudo com suspeita de torção. Qual é o principal erro a evitar?", "alternativas": ["Encaminhar para urologia sem exame físico completo", "Dispensar o exame do testículo contralateral, por rotina", "Analgesia isolada e reavaliação ambulatorial em dois dias", "Não registrar a hora de início, pois não altera a conduta", "Atrasar a cirurgia à espera de antibiótico ou de exames"], "gabarito": "E", "justificativa": "Na torção, o tempo é o fator decisivo: atrasar a cirurgia à espera de exames ou antibiótico reduz a chance de salvar o testículo.", "epônimo": null, "tecnica": "Torção", "slide": 73}], "casos_extremos": [{"titulo": "Caso T1 · Dor escrotal com episódios que cederam", "texto": "Adolescente de 15 anos apresenta dor escrotal esquerda de início súbito há 2 horas, com náusea. Já teve dois episódios semelhantes que cederam espontaneamente em menos de uma hora. Ao exame, testículo esquerdo alto e horizontal, cremastérico ausente à esquerda, sem febre. Urina normal.", "perguntas": [{"pergunta": "Qual é a hipótese prioritária e a urgência?", "alternativas": ["Epididimite, com antibiótico oral por dez dias", "Torção testicular intermitente, com urgência cirúrgica mesmo após episódios que cederam", "Hidrocele, com observação e controle clínico", "Varicocele, com investigação eletiva e exame programado", "Hérnia escrotal redutível, com redução manual imediata"], "gabarito": "B", "justificativa": "Episódios que cedem espontaneamente sugerem torção intermitente; testículo alto e horizontal com cremastérico ausente exige cirurgia urgente."}, {"pergunta": "Qual é o principal erro que o quadro desafia, considerando o tempo de sintomas?", "alternativas": ["Atrasar a cirurgia por causa dos episódios anteriores que cederam", "Realizar ultrassonografia com Doppler antes de decidir a conduta", "Registrar a hora de início da dor no prontuário", "Comparar com o testículo contralateral no exame físico", "Solicitar urina tipo I antes de qualquer decisão cirúrgica"], "gabarito": "A", "justificativa": "A torção intermitente cede e recorre; atribuir o quadro atual a episódios anteriores que cederam é o erro que atrasa a salvação do testículo."}]}, {"titulo": "Caso T2 · Massa escrotal com transluminação parcial", "texto": "Homem de 35 anos apresenta massa escrotal direita, indolor, com transluminação parcial, que os dedos não ultrapassam superiormente. Ao esforço em pé com Valsalva, há aumento discreto e a massa se torna mais palpável no cordão. Testículo direito palpável, de tamanho normal, separado da massa.", "perguntas": [{"pergunta": "Qual é a hipótese mais provável diante da palpação acima da massa e do esforço?", "alternativas": ["Hérnia escrotal, pois os dedos não passam acima da massa", "Hidrocele, pois os dedos passam acima da massa escrotal", "Tumor testicular sólido, sem transluminação e com nódulo duro", "Epididimite crônica, com nódulo indolor e transluminação", "Espermatocele com cordão normal e sem aumento ao esforço"], "gabarito": "A", "justificativa": "Na hérnia escrotal os dedos não ultrapassam superiormente a massa, e o aumento ao esforço sugere continuidade com o canal inguinal."}, {"pergunta": "Qual é a manobra complementar que confirma a continuidade com o canal inguinal?", "alternativas": ["Pesquisa de dor à palpação do epidídimo em decúbito", "Invaginação da pele escrotal até o anel inguinal, com tosse", "Transiluminação com lanterna de alta potência, sem tosse", "Palpação prostática pelo toque retal, em decúbito lateral", "Medida da circunferência escrotal com fita métrica"], "gabarito": "B", "justificativa": "A invaginação da pele escrotal até o anel inguinal superficial, com tosse, pesquisa a hérnia inguinal indireta ou direta."}]}, {"titulo": "Caso T3 · Próstata com sintomas e toque alterado", "texto": "Homem de 68 anos, com noctúria de 4 episódios e jato urinário fraco há 2 anos, apresenta ao toque retal próstata aumentada, lisa, simétrica e elástica, com sulco mediano apagado em um lado, sem dor. PSA 3,8 ng/mL. Não há febre nem hematúria.", "perguntas": [{"pergunta": "Qual é a interpretação do toque retal e dos sintomas?", "alternativas": ["Câncer de próstata confirmado, pelo sulco apagado isolado", "Hiperplasia prostática benigna, com sulco apagado isolado possível", "Prostatite aguda, pelo aumento de volume da glândula prostática", "Normalidade, pois o sulco mediano nunca se altera no exame", "Abscesso prostático, pelo sulco apagado e pela consistência"], "gabarito": "B", "justificativa": "O sulco apagado isolado ocorre na hiperplasia benigna; achados como nódulo duro ou área pétrea exigem investigação adicional."}, {"pergunta": "Qual é a conduta mais adequada diante do PSA e do toque retal?", "alternativas": ["Alta com retorno apenas se houver dor local persistente", "Avaliação urológica com decisão compartilhada, conforme risco", "Cirurgia de ressecção imediata, sem avaliação complementar", "Antibiótico de amplo espectro por dez dias, sem cultura", "Corticoide oral por trinta dias, com reavaliação em um mês"], "gabarito": "B", "justificativa": "PSA e toque retal orientam decisão compartilhada, com avaliação urológica e investigação conforme risco, e não ação imediata isolada."}]}]};
